package justepicdimensions.pregen;

import com.google.gson.*;
import java.util.*;
import justepicdimensions.definition.*;
import net.minecraft.resources.ResourceLocation;

/** Reusable selection and work policy. Coordinates are frozen for each actual backend task. */
public record JEDPregenerationPolicy(ResourceLocation id,String shape,Area area,String pattern,String arrivals,boolean initial,boolean afterReset,Workload workload,long maxChunks){
    public static final String DIRECTORY="justepicdimensions/pregeneration";
    public record Area(String source,boolean spawn,double x,double z,double radiusX,double radiusZ,double inset){}
    public record Workload(String mode,double pauseTps,double resumeTps,int delaySeconds){}
    public record Plan(String shape,double x,double z,double radiusX,double radiusZ,String pattern){
        public JsonObject json(){var json=new JsonObject();json.addProperty("shape",shape);json.addProperty("x",x);json.addProperty("z",z);json.addProperty("radius_x",radiusX);json.addProperty("radius_z",radiusZ);json.addProperty("pattern",pattern);return json;}
        public long upperBound(){long minX=(long)Math.floor((x-radiusX)/16),maxX=(long)Math.floor((x+radiusX)/16),minZ=(long)Math.floor((z-radiusZ)/16),maxZ=(long)Math.floor((z+radiusZ)/16);return Math.multiplyExact(Math.addExact(maxX-minX,1),Math.addExact(maxZ-minZ,1));}
        public static Plan read(JsonObject json){JEDJson.keys(json,Set.of("shape","x","z","radius_x","radius_z","pattern"),"pregeneration plan");for(String key:List.of("x","z","radius_x","radius_z"))if(!json.has(key))throw new JEDDefinitionException("Missing saved selection "+key);String shape=choice(json,"shape",null,Set.of("square","circle","rectangle","ellipse","diamond"));String pattern=choice(json,"pattern",null,Set.of("concentric","loop","spiral"));var plan=new Plan(shape,number(json,"x",0,-29999984,29999984),number(json,"z",0,-29999984,29999984),number(json,"radius_x",0,1,29999984),number(json,"radius_z",0,1,29999984),pattern);bounds(plan);if(!shape.equals("rectangle")&&!shape.equals("ellipse")&&plan.radiusX()!=plan.radiusZ())throw new JEDDefinitionException("Unequal radii require rectangle or ellipse");return plan;}
    }
    public Plan plan(double spawnX,double spawnZ,double borderX,double borderZ,double borderSize){
        double x=area.source().equals("border")?borderX:area.spawn()?spawnX:area.x(),z=area.source().equals("border")?borderZ:area.spawn()?spawnZ:area.z();double rx=area.source().equals("border")?borderSize/2-area.inset():area.radiusX(),rz=area.source().equals("border")?rx:area.radiusZ();var plan=new Plan(shape,x,z,rx,rz,pattern);bounds(plan);if(plan.upperBound()>maxChunks)throw new JEDDefinitionException(id+": the area covers up to "+String.format(java.util.Locale.ROOT,"%,d",plan.upperBound())+" chunks, above its max_chunks of "+String.format(java.util.Locale.ROOT,"%,d",maxChunks)+". "+(area.source().equals("border")?"Raise area.inset or shrink the world border":"Lower area.radius")+", or raise max_chunks in that policy file.");return plan;
    }
    public String signature(){var json=new JsonObject();json.addProperty("id",id.toString());json.addProperty("shape",shape);json.addProperty("area",area.toString());json.addProperty("pattern",pattern);return justepicdimensions.bundle.JEDDimensionBundle.hash(justepicdimensions.bundle.JEDDimensionBundle.json(json));}
    private static void bounds(Plan plan){for(double value:new double[]{plan.x(),plan.z(),plan.radiusX(),plan.radiusZ()})if(!Double.isFinite(value))throw new JEDDefinitionException("Non-finite pregeneration bounds");if(plan.radiusX()<1||plan.radiusZ()<1||Math.abs(plan.x())+plan.radiusX()>29999984||Math.abs(plan.z())+plan.radiusZ()>29999984)throw new JEDDefinitionException("Pregeneration area is outside native world bounds");}
    public static JEDPregenerationPolicy decode(ResourceLocation id,JEDSourceDocument document){
        var json=JEDJson.object(document.value(),id.toString());JEDJson.keys(json,Set.of("format_version","shape","area","pattern","arrivals","automatic","workload","max_chunks"),id.toString());if(JEDJson.integer(json.get("format_version"),id+".format_version")!=1)throw new JEDDefinitionException(id+": unsupported pregeneration policy version");
        String shape=choice(json,"shape","square",Set.of("square","circle","rectangle","ellipse","diamond"));String pattern=choice(json,"pattern","concentric",Set.of("concentric","loop","spiral"));String arrivals=choice(json,"arrivals","ordinary",Set.of("ordinary","all","open"));var raw=JEDJson.object(json.get("area"),id+".area");JEDJson.keys(raw,Set.of("source","center","radius","radius_x","radius_z","inset"),id+".area");String source=choice(raw,"source","radius",Set.of("radius","border"));boolean spawn=true;double x=0,z=0,rx=0,rz=0,inset=0;
        if(source.equals("border")){reject(raw,"center","radius","radius_x","radius_z");inset=number(raw,"inset",0,0,29999984);}else{reject(raw,"inset");if(raw.has("center")){var center=raw.get("center");if(center.isJsonPrimitive()&&center.getAsJsonPrimitive().isString()){if(!center.getAsString().equals("spawn"))throw new JEDDefinitionException(id+": center must be spawn or [x,z]");}else{if(!center.isJsonArray()||center.getAsJsonArray().size()!=2)throw new JEDDefinitionException(id+": center must have two coordinates");spawn=false;var coordinates=new JsonObject();coordinates.add("x",center.getAsJsonArray().get(0));coordinates.add("z",center.getAsJsonArray().get(1));x=number(coordinates,"x",0,-29999984,29999984);z=number(coordinates,"z",0,-29999984,29999984);}}
            if(raw.has("radius")){reject(raw,"radius_x","radius_z");rx=rz=number(raw,"radius",0,1,29999984);}else{rx=number(raw,"radius_x",0,1,29999984);rz=number(raw,"radius_z",0,1,29999984);if(rx==0||rz==0)throw new JEDDefinitionException(id+": an explicit bounded radius is required");}if(!shape.equals("rectangle")&&!shape.equals("ellipse")&&rx!=rz)throw new JEDDefinitionException(id+": unequal radii require rectangle or ellipse");}
        var automatic=json.has("automatic")?JEDJson.object(json.get("automatic"),id+".automatic"):new JsonObject();JEDJson.keys(automatic,Set.of("initial","after_reset"),id+".automatic");
        var work=json.has("workload")?JEDJson.object(json.get("workload"),id+".workload"):new JsonObject();JEDJson.keys(work,Set.of("mode","pause_below_tps","resume_above_tps","recovery_seconds"),id+".workload");String mode=choice(work,"mode","tps",Set.of("tps","empty","manual"));double pause=number(work,"pause_below_tps",18,1,20),resume=number(work,"resume_above_tps",19,1,20);if(resume<=pause)throw new JEDDefinitionException(id+": resume TPS must exceed pause TPS");int delay=integer(work,"recovery_seconds",10,1,3600);long cap=integer(json,"max_chunks",1000000,1,Integer.MAX_VALUE);return new JEDPregenerationPolicy(id,shape,new Area(source,spawn,x,z,rx,rz,inset),pattern,arrivals,flag(automatic,"initial",false),flag(automatic,"after_reset",false),new Workload(mode,pause,resume,delay),cap);
    }
    static String choice(JsonObject json,String key,String fallback,Set<String> choices){String value=json.has(key)?JEDJson.string(json.get(key),key):fallback;if(value==null||!choices.contains(value))throw new JEDDefinitionException(key+": choose "+new TreeSet<>(choices));return value;}
    static boolean flag(JsonObject json,String key,boolean fallback){if(!json.has(key))return fallback;var value=json.get(key);if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isBoolean())throw new JEDDefinitionException(key+": expected a boolean");return value.getAsBoolean();}
    static double number(JsonObject json,String key,double fallback,double min,double max){if(!json.has(key))return fallback;var value=json.get(key);if(!value.isJsonPrimitive()||!value.getAsJsonPrimitive().isNumber()||!Double.isFinite(value.getAsDouble())||value.getAsDouble()<min||value.getAsDouble()>max)throw new JEDDefinitionException(key+": number outside "+min+".."+max);return value.getAsDouble();}
    static int integer(JsonObject json,String key,int fallback,int min,int max){if(!json.has(key))return fallback;int value=JEDJson.integer(json.get(key),key);if(value<min||value>max)throw new JEDDefinitionException(key+": number outside "+min+".."+max);return value;}
    private static void reject(JsonObject json,String... keys){for(String key:keys)if(json.has(key))throw new JEDDefinitionException(key+": does not apply to this selection");}
}
